DO $cost$
DECLARE tree jsonb:='[]';trees jsonb;head jsonb;heads jsonb;model jsonb;template jsonb;c public.gto_v31_runtime_cells;i integer;k text;started timestamptz;ms numeric;cnt integer;d public.gto_v31_datasets;b public.gto_v31_input_bundles;r record;cases jsonb:='[]';approved jsonb:='[]';own jsonb;lo integer;hi integer;receipt jsonb;bad public.gto_v31_runtime_cells;
BEGIN
 FOR i IN 0..13 LOOP tree:=tree||jsonb_build_array(jsonb_build_object('feature',i,'threshold_f64','0000000000000000','left',CASE WHEN i<13 THEN i+1 ELSE 27 END,'right',CASE WHEN i<13 THEN 14+i ELSE 28 END,'missing_left',false));END LOOP;
 FOR i IN 14..28 LOOP tree:=tree||jsonb_build_array(jsonb_build_object('value_f64','0000000000000000'));END LOOP;
 SELECT jsonb_agg(tree) INTO trees FROM generate_series(1,100);head:=jsonb_build_object('baseline_f64','3ff0000000000000','trees',trees);SELECT jsonb_agg(head) INTO heads FROM generate_series(1,7);
 template:=jsonb_build_object('format','public_hist215_template_v1','context',jsonb_build_object('street','flop','game_family','cash','objective','cash_ev','utility_context','cash_ev','table_size',2,'pot_type','srp','hero_position','SB','opponent_position','BB','depth_bucket',40,'texture_class','Brud','node_role','open','facing_kind','none','facing_size_bucket','none'),'root_actor','IP','scenario',jsonb_build_object('pot_chips_f64','408f400000000000','effective_stack_chips_f64','40af400000000000','chips_per_bb_f64','4059000000000000','rake_f64',jsonb_build_array('0000000000000000','0000000000000000'),'ip_range_checksum','01b3d4e721b36cf6d8d89fd4941b5ece0e9fd2853f61d1e5f98fbebb3f8f5228','oop_range_checksum','3ac1e6fa6d92a000680addaf06eab130d2af9467d2e90aceae7cb542b8725c11'),'opponent_weights',(SELECT jsonb_agg('1'::text)FROM generate_series(1,1326)));
 model:=jsonb_build_object('format','public_hist215_v1','variant','coherent','feature_count',215,'action_ids',jsonb_build_array('c','b250','b8000'),'heads',heads,'template_sha256',public.fn_gto_v31_public215_digest(template),'feature_schema_sha256','0ca054f9bb0463bf6a298a80a29cb4b6d9e6bffcc193e4af9d497e2936ec849f','provenance_sha256',repeat('c',64));
 c.policy_representation:='public_hist215_v1';c.public_model:=model;c.model_checksum:=public.fn_gto_v31_public215_digest(model);c.public_template:=template;c.template_checksum:=public.fn_gto_v31_public215_digest(template);
 started:=clock_timestamp();k:=public.fn_gto_v31_public215_prepare_audit(c,ARRAY['Qh','7d','2c']);ms:=extract(epoch FROM clock_timestamp()-started)*1000;
 SELECT count(*)INTO cnt FROM public.gto_v31_public_model_audit_combos a WHERE audit_key=k AND cardinality(features)=215 AND cardinality(raw_heads)=7 AND policy_ev=1 AND frequencies=ARRAY[1::double precision/3,1::double precision/3,1::double precision/3];
 IF cnt<>1176 THEN RAISE EXCEPTION 'complete independent215/allhead audit oracle count %',cnt;END IF;
 d.dataset_id:='21500000-0000-4000-8000-000000000001';b.bundle_checksum:=repeat('a',64);c.training_provenance_checksum:=repeat('c',64);c.feature_schema_checksum:=model->>'feature_schema_sha256';c.public_training_provenance:=jsonb_build_object('encoder_checksum',repeat('d',64),'physics_checksum',repeat('e',64),'dependency_lock_checksum',repeat('f',64),'producer_commit',repeat('a',40),'producer_bundle_checksum',repeat('b',64));
 FOR r IN SELECT * FROM public.gto_v31_public_model_audit_combos WHERE audit_key=k ORDER BY combo LIMIT 2 LOOP
  hi:=floor((1+sqrt(1+8*r.combo))/2)::integer;WHILE hi*(hi-1)/2>r.combo LOOP hi:=hi-1;END LOOP;lo:=r.combo-hi*(hi-1)/2;own:=jsonb_build_array(substr('23456789TJQKA',lo/4+1,1)||substr('cdhs',lo%4+1,1),substr('23456789TJQKA',hi/4+1,1)||substr('cdhs',hi%4+1,1));
  approved:=approved||jsonb_build_array(jsonb_build_object('board','Qh7d2c','own',own));
  cases:=cases||jsonb_build_array(jsonb_build_object('board','Qh7d2c','own',own,'features_f64',public.fn_gto_v31_public215_bits(r.features),'raw_heads_f64',public.fn_gto_v31_public215_bits(r.raw_heads),'policy_ev_f64',encode(float8send(r.policy_ev),'hex'),'Q_f64',public.fn_gto_v31_public215_bits(r.action_evs),'frequency_f64',public.fn_gto_v31_public215_bits(r.frequencies),'physics_ms_f64','3ff0000000000000','inference_ms_f64','4000000000000000'));
 END LOOP;
 b.bundle_manifest:=jsonb_build_object('public215_protocols',jsonb_build_object('runtime_parity_protocol',jsonb_build_object('contexts',jsonb_build_array(jsonb_build_object('context',template->'context','cases',approved)))));
 receipt:=jsonb_build_object('format','public_hist215_build_receipt_v1','dataset_id',d.dataset_id,'input_bundle_checksum',b.bundle_checksum,'model_checksum',c.model_checksum,'training_provenance_checksum',c.training_provenance_checksum,'template_checksum',c.template_checksum,'feature_schema_checksum',c.feature_schema_checksum,'encoder_checksum',repeat('d',64),'physics_checksum',repeat('e',64),'dependency_lock_checksum',repeat('f',64),'producer_commit',repeat('a',40),'producer_bundle_checksum',repeat('b',64),'runtime',jsonb_build_object('node_version','v22.23.3','platform','linux','arch','x64','napi_version',8,'native_source_checksum','83442cb6604dfaa30ec7ecc6ce38957355609e722b5df85b866365c97f0ccf9b','native_binary_checksum',repeat('d',64)),'cases',cases,'cost',jsonb_build_object('method','cold_public215_features_and_all_heads_v1','clock','process.hrtime.bigint','cold_cases',2,'max_physics_ms_f64','3ff0000000000000','max_inference_ms_f64','4000000000000000','execution_limit_ms',8000,'model_bytes',octet_length(public.fn_gto_v31_public215_canonical(model)),'head_count',7));
 c.public_model_build_receipt:=receipt;c.model_build_receipt_checksum:=public.fn_gto_v31_public215_digest(receipt);
 IF public.fn_gto_v31_public215_build_receipt(c,d,b) IS NOT TRUE THEN RAISE EXCEPTION 'independent complete case receipt rejected';END IF;
 bad:=c;bad.public_model_build_receipt:=jsonb_set(receipt,'{cases,0,features_f64,0}','"3ff0000000000000"');bad.model_build_receipt_checksum:=public.fn_gto_v31_public215_digest(bad.public_model_build_receipt);IF public.fn_gto_v31_public215_build_receipt(bad,d,b) IS NOT FALSE THEN RAISE EXCEPTION 'forged feature receipt accepted';END IF;
 bad:=c;bad.public_model_build_receipt:=jsonb_set(receipt,'{runtime,platform}','"darwin"');bad.model_build_receipt_checksum:=public.fn_gto_v31_public215_digest(bad.public_model_build_receipt);IF public.fn_gto_v31_public215_build_receipt(bad,d,b) IS NOT FALSE THEN RAISE EXCEPTION 'Mac cost accepted as production';END IF;
 bad:=c;bad.public_model_build_receipt:=jsonb_set(receipt,'{cases,0,physics_ms_f64}','null');bad.model_build_receipt_checksum:=public.fn_gto_v31_public215_digest(bad.public_model_build_receipt);IF public.fn_gto_v31_public215_build_receipt(bad,d,b) IS NOT FALSE THEN RAISE EXCEPTION 'null cost accepted';END IF;
 IF public.fn_gto_v31_public215_audit_prediction(c,'Qh7d2c',(SELECT min(combo)FROM public.gto_v31_public_model_audit_combos WHERE audit_key=k))->>'policy'<>'1' THEN RAISE EXCEPTION 'audit consumer oracle';END IF;
 BEGIN PERFORM public.fn_gto_v31_public215_audit_prediction(c,'Qh7d3c',1000);RAISE EXCEPTION 'missing audit accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM='missing audit accepted' THEN RAISE;END IF;END;
 RAISE NOTICE 'PUBLIC215_INDEPENDENT_RECEIPT_FORGERY_AND_MISSING_AUDIT_GUARDS_PASS';
 RAISE NOTICE 'PUBLIC215_FULL_FEATURES_H7_100TREES_ALL1176_AUDIT_PASS total_ms=% auditkey=%',ms,k;
END $cost$;
